2	/**
3	 * resolve_resume_agent.ts — Decide which agent `/resume` means.
4	 *
5	 * `/resume` is `/<agent>` with the name filled in from what actually ran here, so a
6	 * person who wants to continue does not have to remember whether it was the engineer
7	 * or the reviewer. That is the only thing it does differently, which is why it takes
8	 * no instruction: `/<agent>` already resumes the same session AND carries one.
9	 *
10	 * The name is read from the thread rather than stored anywhere, the same choice
11	 * `dispatch-chain.ts` makes about handoffs. Every result comment already carries
12	 * `AGENT_TAG` -- `post_result_comment.ts` writes it so a later run can recognise its
13	 * own past output -- so the most recent one is the answer, and there is nothing extra
14	 * to keep in sync.
15	 *
16	 * Writes `agent` to $GITHUB_OUTPUT, empty when there is nothing to resume.
17	 *
18	 * Usage:
19	 *   resolve_resume_agent.ts --number N
20	 */
21	import { appendFileSync } from "node:fs";
22	import { parseArgs } from "node:util";
23	import { gh, ghPaginated } from "../../adapters/github/gh.ts";
24	import { LLM_CONTEXT_TAG } from "../../adapters/github/tags.ts";
25	import { mostRecentAgent, mostRecentAgentOn } from "../../adapters/github/agent-on-issue.ts";
26	import { defineScript } from "./lib/script-ref.ts";
27	
28	export interface ResolveResumeAgentArgs {
29	  number: string | number;
30	}
31	
32	export const ref = defineScript<ResolveResumeAgentArgs>(import.meta.url);
33	
34	// `mostRecentAgent` and `mostRecentAgentOn` were defined here and are now in
35	// `adapters/github/agent-on-issue.ts`. The aggregation gate needed the same
36	// question answered -- "who was working on this node" -- and `app/` may not import
37	// from `entrypoints/`, so the reader moved to the layer both can reach. Re-exported
38	// because this module's own tests and `resume_subtree.ts` import them from here.
39	export { mostRecentAgent, mostRecentAgentOn };
40	
41	function main(): void {
42	  const { values } = parseArgs({ args: Bun.argv.slice(2), options: { number: { type: "string" } } });
43	  if (!values.number) {
44	    console.error("usage: resolve_resume_agent.ts --number N");
45	    process.exit(2);
46	  }
47	
48	  const repo = process.env.GITHUB_REPOSITORY ?? "";
49	  // `ghPaginated`, not a `JSON.parse` of the whole stdout: with `--paginate`, `gh`
50	  // evaluates `--jq` once per page and writes each page's result to the same
